<script>
  import {onDestroy} from 'svelte';import {client,createLoader,changed,isAbort} from '../lib/api.js';import {href} from '../lib/router.js';import Button from '../components/Button.svelte';import Icon from '../components/Icon.svelte';import Notice from '../components/Notice.svelte';import Select from '../components/Select.svelte';
  export let lang='vi';const preview=createLoader();let file,name='',slug='',mapping={},busy=false,error='',alive=true,input;
  $: t=(vi,en)=>lang==='en'?en:vi;
  $: plan=$preview.data;
  const fields=[['name','Tên sản phẩm / dữ liệu','Name'],['sku','Mã dòng','Row key'],['category','Danh mục','Category'],['brand','Thương hiệu','Brand'],['price','Giá','Price']];
  function form(mapped=false){const data=new FormData();data.append('file',file);if(mapped)data.append('mapping',JSON.stringify(Object.fromEntries(Object.entries(mapping).filter(([,v])=>v))));return data;}
  async function read(mapped=false){if(!file)return;const current=file;const result=await preview.load(signal=>client.request('/v1/tables/preview',{method:'POST',body:form(mapped),signal,timeout:60000}));if(alive&&file===current&&result){mapping={...result.mapping};if(!slug)slug=result.suggested_slug;}}
  function choose(e){file=e.currentTarget.files?.[0];error='';preview.clear();slug='';mapping={};if(file?.size>20*1024*1024){error=t('File vượt quá giới hạn 20 MB.','File exceeds 20 MB.');file=null;input.value='';return;}if(file){if(!name)name=file.name.replace(/\.[^.]+$/,'');read();}}
  async function create(){if(busy||!plan||!file)return;busy=true;error='';const data=form(true);data.append('name',name.trim()||plan.suggested_slug);data.append('slug',slug.trim()||plan.suggested_slug);
    try{const result=await client.mutate('create-table',()=>client.request('/v1/tables',{method:'POST',body:data}));changed(result.slug,result);if(alive)location.hash=href(result.slug,'api');}catch(e){if(alive&&!isAbort(e))error=e.message;}finally{if(alive)busy=false;}}
  onDestroy(()=>{alive=false;preview.dispose();file=null;});
</script>
<p class="text-muted mb-6 max-w-2xl">{t('Nhập Excel, CSV hoặc JSON. Xem trước và chọn cột, sau đó tạo bảng để bắt đầu tìm kiếm.','Import Excel, CSV or JSON. Preview and map columns, then create a searchable table.')}</p>
<Notice {error} {lang}/><Notice error={$preview.error} retry={()=>read()} {lang}/>
<section class="panel"><div class="grid md:grid-cols-3 gap-5"><label class="field"><span>{t('File dữ liệu','Data file')}</span><input bind:this={input} type="file" accept=".xlsx,.xls,.csv,.json,.jsonl" disabled={busy} on:change={choose}/></label><label class="field"><span>{t('Tên bảng','Table name')}</span><input bind:value={name} maxlength="200" disabled={busy}/></label><label class="field"><span>Slug</span><input bind:value={slug} placeholder="vi-du-bang-du-lieu" pattern="[a-z0-9][a-z0-9_-]{1,63}" disabled={busy}/></label></div><div class="mt-5"><Button busy={$preview.loading} disabled={!file||busy} on:click={()=>read()}><Icon name="upload" size={17}/>{t('Đọc và xem trước','Read and preview')}</Button></div></section>
{#if plan}<div class="space-y-5 mt-5"><section class="panel"><h2>{t('Chọn cột dữ liệu','Map columns')}</h2><div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4 mt-5">{#each fields as [key,vi,en]}<div class="field"><span>{lang==='vi'?vi:en}{key==='name'?' *':''}</span><Select bind:value={mapping[key]} disabled={busy} label={lang==='vi'?vi:en} options={[{value:'',label:t('Không chọn','None')},...plan.columns.map(c=>({value:c,label:c}))]}/></div>{/each}</div><div class="mt-5"><Button busy={$preview.loading} disabled={busy} on:click={()=>read(true)}>{t('Cập nhật ánh xạ','Update mapping')}</Button></div>{#if plan.proposed_definitions?.length}<p class="text-xs text-muted mt-5 mb-3">{t('Thuộc tính tìm kiếm','Search attributes')}</p><div class="flex flex-wrap gap-2">{#each plan.proposed_definitions as d}<span class="badge">{d.label} · {d.type}</span>{/each}</div>{/if}{#if plan.warnings?.length}<details class="mt-5"><summary class="text-amber-800 cursor-pointer">{plan.warnings.length} {t('cảnh báo','warnings')}</summary><pre class="whitespace-pre-wrap text-xs mt-3">{plan.warnings.join('\n')}</pre></details>{/if}</section><section class="panel"><h2 class="mb-5">{plan.n_rows} {t('dòng hợp lệ','valid rows')}</h2><div class="table-scroll"><table class="data-table"><thead><tr>{#each plan.columns as col}<th>{col}</th>{/each}</tr></thead><tbody>{#each plan.preview as row}<tr>{#each plan.columns as col}<td class="truncate max-w-52">{String(row[col]??'')}</td>{/each}</tr>{/each}</tbody></table></div><div class="mt-5"><Button variant="primary" {busy} disabled={!plan.n_rows||!mapping.name||$preview.loading} on:click={create}>{busy?t('Đang tạo bảng…','Creating table…'):t('Tạo bảng và embedding','Create table and embeddings')}<Icon name="arrow" size={16}/></Button></div></section></div>{/if}
